import java.util.*;

class Solution {
    public int maxTwoTrips(int[] prices) {
        int buy1 = Integer.MIN_VALUE, buy2 = Integer.MIN_VALUE;
        int sell1 = 0, sell2 = 0;
        for (int p : prices) {
            buy1 = Math.max(buy1, -p);          // best after first buy
            sell1 = Math.max(sell1, buy1 + p);  // best after first sell
            buy2 = Math.max(buy2, sell1 - p);   // second buy uses first trip's profit
            sell2 = Math.max(sell2, buy2 + p);  // best after second sell
        }
        return sell2;
    }
}

