function maxTwoTrips(prices) {
  const n = prices.length;
  const left = new Array(n).fill(0), right = new Array(n + 1).fill(0);
  let mn = prices[0];
  for (let i = 1; i < n; i++) { mn = Math.min(mn, prices[i]); left[i] = Math.max(left[i-1], prices[i] - mn); }
  let mx = prices[n-1];
  for (let i = n - 2; i >= 0; i--) { mx = Math.max(mx, prices[i]); right[i] = Math.max(right[i+1], mx - prices[i]); }
  let best = 0;
  for (let i = 0; i < n; i++) best = Math.max(best, left[i] + right[i + 1 <= n ? i + 1 : n]);
  return Math.max(best, right[0]);
}
